
.duration-selector {
	display: flex;
	flex-direction: column;
	gap: calc(var(--default-grid-baseline) * 2);
	width: 100%;
	max-width: 100%;
	overflow: hidden;
}

.duration-selector__custom-controls {
	display: flex;
	gap: calc(var(--default-grid-baseline) * 2);
	flex-wrap: nowrap;
	width: 100%;
	max-width: 100%;
	overflow: hidden;
}

.duration-selector__custom-select {
	flex: 1 1 0;
	min-width: 0 !important;
	max-width: 100%;
	margin: 0;
	width: 100%;

	:deep(.vs__selected) {
		white-space: nowrap;
		overflow: hidden;
		text-overflow: ellipsis;
		max-width: 100%;
	}
}
